UPDATE zangraf_products AS product
SET data=jsonb_set(jsonb_set(product.data,'{albumPricing}',source.value->'albumPricing'),'{options,finishes}',source.value->'finishes'),updated_at=now()
FROM source
WHERE EXISTS(SELECT 1 FROM zg_layflat_import_once)
 AND product.id=source.value->>'id'
 AND COALESCE(product.data->>'kind','album')='album'
 AND product.data->'options'->'sizes'=jsonb_build_array(source.value->>'size')
 AND lower(regexp_replace(product.data->'options'->'covers'->>0,'[- ]','','g'))=ANY(ARRAY[lower(regexp_replace(source.value->>'cover','[- ]','','g')),CASE WHEN source.value->>'cover'='Anti-Risco' THEN 'antirrisco' ELSE '' END])
 AND (product.data->>'priceCents') IS NULL
 AND COALESCE(product.data->'albumPricing','[]'::jsonb)=source.value->'previousPricing'
 AND COALESCE(product.data->'options'->'finishes','[]'::jsonb)=source.value->'previousFinishes';
UPDATE zangraf_products SET data=jsonb_set(jsonb_set(data,'{options,sheets}','["10 lâminas","15 lâminas","20 lâminas","25 lâminas","30 lâminas","35 lâminas","40 lâminas"]'::jsonb),'{description}',to_jsonb(replace(data->>'description','10 a 60 lâminas (20 a 120 páginas)','10 a 40 lâminas (20 a 80 páginas)'))),updated_at=now()
WHERE EXISTS(SELECT 1 FROM zg_layflat_import_once)
 AND data->'options'->'covers' @> '["1500 gramas"]'::jsonb;
